(333, 387, 47, '\n            <div class=\"mb-4\" style=\"padding-left: 8px; font-family: system-ui, sans-serif;\">\n                <p class=\"mb-3\" style=\"font-size: 16px; color: #1e293b; margin-bottom: 10px; font-weight: 700;\">\n                    <span style=\"color: #1e293b;\">&bull; Warrgyizmorsch Backend</span>\n                    <span style=\"color: #3858f9; font-weight: 700;\"> - 8h 30m</span>\n                </p>\n                <ol class=\"text-muted\" style=\"font-size: 14px; line-height: 1.9; padding-left: 24px; color: #64748b; margin: 0;\">\n                    <li style=\"margin-bottom: 6px;\">Converted Student Details section to Client Details with updated UI structure.</li><li style=\"margin-bottom: 6px;\">Added dynamic multiple client contact (clone) functionality with add/remove support.</li><li style=\"margin-bottom: 6px;\">Implemented new fields: Employee Strength, Industry, Service, Choose Product, and Pain Points &amp; Current System.</li><li style=\"margin-bottom: 6px;\">Added multi-select Service dropdown functionality.</li><li style=\"margin-bottom: 6px;\">Updated create and edit lead logic for new fields.</li><li style=\"margin-bottom: 6px;\">Added database support and JSON handling for additional client contact details.</li><li style=\"margin-bottom: 6px;\">Updated lead details view to display newly added client information.</li>\n                </ol>\n            </div>', 'Manish patidar', '8.5', NULL, '2026-06-02 12:44:20', '2026-06-02 12:44:20'),
(334, 393, 2, '\n            <div class=\"mb-4\" style=\"padding-left: 8px; font-family: system-ui, sans-serif;\">\n                <p class=\"mb-3\" style=\"font-size: 16px; color: #1e293b; margin-bottom: 10px; font-weight: 700;\">\n                    <span style=\"color: #1e293b;\">&bull; SIP Backend</span>\n                    <span style=\"color: #3858f9; font-weight: 700;\"> - 6h</span>\n                </p>\n                <ol class=\"text-muted\" style=\"font-size: 14px; line-height: 1.9; padding-left: 24px; color: #64748b; margin: 0;\">\n                    <li style=\"margin-bottom: 6px;\">Complete View And Flow Of Capital Gain Statement And Own API According App Behaviour Like Email Send Or Downlaod</li><li style=\"margin-bottom: 6px;\">also Completed  Account Statement With Same FLow API And Backend View</li><li style=\"margin-bottom: 6px;\">Update Same Goal API&#039;s Changes</li>\n                </ol>\n            </div>', 'ANSHUL SUTHAR (KHETA RAM)', '6', NULL, '2026-06-02 12:45:38', '2026-06-02 12:45:38'),
